def predict_hyp2(grid, h_or_v=None):
    """Hypothesis 2: Cell becomes 2 if it's bracketed between two consecutive 9s in row or column"""
    result = grid.copy()

    # Find all 9s in each row
    row_nines = {}
    for r in range(grid.shape[0]):
        nines = []
        for c in range(grid.shape[1]):
            if grid[r, c] == 9:
                nines.append(c)
        row_nines[r] = nines

    # Find all 9s in each column  
    col_nines = {}
    for c in range(grid.shape[1]):
        nines = []
        for r in range(grid.shape[0]):
            if grid[r, c] == 9:
                nines.append(r)
        col_nines[c] = nines

    for r in range(grid.shape[0]):
        for c in range(grid.shape[1]):
            if grid[r, c] != 4:
                continue

            # Check horizontal bracketing
            h_ok = False
            if r in row_nines:
                nines = row_nines[r]
                # Find 9 immediately to the left
                left_idx = -1
                for i, nc in enumerate(nines):
                    if nc < c:
                        left_idx = i
                    else:
                        break
                # Find 9 immediately to the right
                right_idx = len(nines)
                for i in reversed(range(len(nines))):
                    if nines[i] >= c:
                        right_idx = i
                        break

                if left_idx >= 0 and right_idx < len(nines):
                    # Check if these two 9s bracket c consecutively
                    if nines[left_idx] < c < nines[right_idx]:
                        # Check no 9s between them
                        left = nines[left_idx]
                        right = nines[right_idx]
                        all_between_4 = True
                        for k in range(left + 1, right):
                            if grid[r, k] != 4:
                                all_between_4 = False
                                break
                        if all_between_4:
                            h_ok = True

            # Check vertical bracketing
            v_ok = False
            if c in col_nines:
                nines = col_nines[c]
                # Find 9 immediately above
                up_idx = -1
                for i, nr in enumerate(nines):
                    if nr < r:
                        up_idx = i
                    else:
                        break
                # Find 9 immediately below
                down_idx = len(nines)
                for i in reversed(range(len(nines))):
                    if nines[i] >= r:
                        down_idx = i
                        break

                if up_idx >= 0 and down_idx < len(nines):
                    up = nines[up_idx]
                    down = nines[down_idx]
                    if up < r < down:
                        all_between_4 = True
                        for k in range(up + 1, down):
                            if grid[k, c] != 4:
                                all_between_4 = False
                                break
                        if all_between_4:
                            v_ok = True

            if h_ok or v_ok:
                result[r, c] = 2

    return result

